local config = {
  str_help_maze_explain = "Inf. de Explor. do Ter. Secreto",
  str_help_maze_title1 = "Território Secreto",
  str_help_maze_title2 = "Custo de Exp.",
  str_help_maze_title3 = "Atrib. do Aurorian",
  str_help_maze_title4 = "Características do Ter. Secreto",
  str_help_maze_title5 = "Falhou ao Herdar",
  str_help_maze_title6 = "Reiniciar Explor. do Ter. Secreto",
  str_help_maze_title7 = "Loja Secreta",
  str_help_maze_title8 = "Exploração Autom. Território Secreto",
  str_help_maze_details1 = "Cada nível do Território Secreto tem diversos caminhos. Escolha um dos caminhos para chegar na Sala Original e derrote o chefe para prosseguir para o próximo nível.",
  str_help_maze_details2 = "Batalhas no Território Secreto consomem MS, um recurso fixo. Você falhará o desafio se não tiver MS suficiente. MS pode ser recuperado com o tempo e a Fonte de Lúmina. Pesquisas na Colossus podem aumentar a velocidade de recuperação de MS.",
  str_help_maze_details3 = "Todos os Aurorians no Território Secreto recebem atributos fixos. Apenas habilidades e efeitos melhorados recebidos pela Ascensão e Avanço funcionarão. Algumas relíquias também podem aumentar os atributos dos Aurorians.",
  str_help_maze_details4 = "No Território Secreto, Aurorians compartilharão o dano recebido igualmente, e aqueles com 0 PV não conseguirão lutar novamente. Dano recebido por um Aurorian é registrado após a batalha. Aurorians podem recuperar-se com a Fonte de Lúmina e algumas relíquias.",
  str_help_maze_details5 = "O PV de Eclipsitas em um estágio no qual a batalha é perdida será registrado, e você pode mudar sua equipe e continuar a batalha. Porém, se você sair do estágio voluntariamente, tudo será restaurado para o estado original.",
  str_help_maze_details6 = "O Território Secreto passa por 1 ciclo a cada 14 dias. Assim que o tempo da Exploração do Território Secreto acabar, o progresso da exploração é reiniciado e o desafio terá que ser tentado desde o início de novo. Após restaurar, relíquias obtidas serão apagadas.",
  str_help_maze_details7 = "Fragmentos de Texto podem ser obtidos em Estágios de Desafio. Esses Fragmentos de Texto podem ser usados para comprar vários itens e recursos na Loja Secreta.",
  str_help_maze_details8 = "Depois de concluir a sala do chefe nível 5 do Território Secreto, você desbloqueará a função de exploração automática. Todas as salas de batalha podem ser exploradas automaticamente, exceto as fases de chefe.",
  str_help_uispiritdetailgroupcontroller_explain = "Informações",
  str_help_uispiritdetailgroupcontroller_title1 = "Inf.: Atributos Básicos",
  str_help_uispiritdetailgroupcontroller_title2 = "Inf.: de Atrib.",
  str_help_uispiritdetailgroupcontroller_title3 = "Inf.: Habilidades",
  str_help_uispiritdetailgroupcontroller_title4 = "Inf. Bás. de Nv.",
  str_help_uispiritdetailgroupcontroller_title5 = "Inf.: Avanço Aurorian",
  str_help_uispiritdetailgroupcontroller_title6 = "Botão Especial",
  str_help_uispiritdetailgroupcontroller_title7 = "Profissão Aurorian",
  str_help_uispiritdetailgroupcontroller_details1 = "1. Você pode ver o Ataque, a Defesa, o PV e outros atributos de um Aurorian.\n2. Em batalhas, o PV da sua equipe é a soma de todos os PV de seus Aurorians e a Defesa é a soma de todas as Defesas de seus Aurorians. Cada Aurorian causa dano de acordo com seu ATQ.",
  str_help_uispiritdetailgroupcontroller_details2 = "1. Durante batalhas, Aurorians aparecerão e atacarão ao se moverem nas casas correspondentes aos seus elementos.\n2. Há um Círculo de Defesa entre os elementos: Água -> Fogo -> Floresta -> Trovão -> Água.\n3. Aurorians de ranking alto podem ascender para ganhar elementos secundários, que causam 35% de seu dano de ataque.",
  str_help_uispiritdetailgroupcontroller_details3 = "1. Toque para mostrar a Tela de Habilidades, que exibe as habilidades do Aurorian selecionado.\n2. Cada Aurorian possui Habilidades Ativas e Combos. Alguns Aurorians de ranking alto podem desbloquear Habilidades de Equipamento, após Ascensão ou Avanço.",
  str_help_uispiritdetailgroupcontroller_details4 = "1. Melhorar Aurorians pode aumentar seus níveis.\n2. Quando um Aurorian chega no nível máximo, ele pode Ascender.\n3. Quando um Aurorian Ascende, seu nível máximo aumenta e o Aurorian alcançará Ascensão I, sem redução de seus atributos.",
  str_help_uispiritdetailgroupcontroller_details5 = "1. Estágios de Avanço Aurorian estão relacionados à Magnitude do Aurorian.\n2. Quanto maior a Magnitude do Aurorian, mais estágios de Avanço estarão disponíveis para ele.\n3. Após o Avanço, a cor da Magnitude mudará de acordo com o estágio correspondente.",
  str_help_uispiritdetailgroupcontroller_details6 = "1. Afinidade é o grau de afinidade entre Aurorians e o personagem principal.\n2. Você pode ver perfis e diálogos Aurorian em seus Arquivos.",
  str_help_uispiritdetailgroupcontroller_details7 = "1. Conversores são especialistas em controlar o Tabuleiro de Alquimia. Eles podem mudar os elementos das casas no Tabuleiro de Alquimia ou trocar suas próprias posições. São personagens indispensáveis para executar estratégias de batalha.\n2. Detonadores são atacantes poderosos que podem atacar múltiplos alvos no tabuleiro com seus ataques amplos e causar dano massivo em inimigos grandes.\n3. Atiradores são personagens que podem matar inimigos individuais com precisão. Possuem um dano alto e são recomendados para atacar inimigos pequenos.\n4. Suportes são personagens que fornecem cura contínua além de vários buffs. Com suas habilidades especiais, eles podem melhorar a capacidade de luta da equipe.",
  str_help_uigradeInterfacecontroller_explain = "Inf.: Ascensão Aurorian",
  str_help_uigradeInterfacecontroller_title1 = "Inf.: Condição de Asc.",
  str_help_uigradeInterfacecontroller_title2 = "Inf.: Atributo de Asc.",
  str_help_uigradeInterfacecontroller_title3 = "Dados de Progressão",
  str_help_uigradeInterfacecontroller_details1 = "1. Aurorians devem alcançar o nível máximo da fase atual para ascender.\n2. Ascensão custa Noitium e materiais.\n3. Conclua Missões Principais por materiais para ascender.",
  str_help_uigradeInterfacecontroller_details2 = "Alguns Aurorians com 5 estrelas ou mais podem despertar seus elementos secundários após alcançar Ascensão III.",
  str_help_uigradeInterfacecontroller_details3 = "Toque no botão Informação de Progressão para abrir a tela e exibir as informações dos Aurorians.",
  str_help_uibreakcontroller_explain = "Inf.: Avanço Aurorian",
  str_help_uibreakcontroller_title1 = "Inf.: Condição de Avanço",
  str_help_uibreakcontroller_title2 = "Inf.: Troca de Mag.",
  str_help_uibreakcontroller_title3 = "Inf.: Rota Est.",
  str_help_uibreakcontroller_title4 = "Dados de Progressão",
  str_help_uibreakcontroller_title5 = "Descrição do Resgate de Solamber",
  str_help_uibreakcontroller_details1 = "1. Aurorians duplicados são convertidos automaticamente em Solâmbar e Pedras-Coração específicas de Aurorians.\n2. Solâmbar Aurorian permite avanços.",
  str_help_uibreakcontroller_details2 = "1. A Magnitude de um Aurorian é o número total de estágios de Avanço disponíveis.\n2. Cada estágio avançado mudará as avaliações correspondentes.",
  str_help_uibreakcontroller_details3 = "1. Os dois lados da estrela em forma de cruz mostrarão se o estágio está melhorando uma habilidade ou um atributo.\n2. Toque nas estrelas em forma de cruz para ver os detalhes do conteúdo melhorado pelo estágio.",
  str_help_uibreakcontroller_details4 = "1. Ao subir o nível de atributos, os atributos recebidos serão mostrados.\n2. Ao subir o nível de habilidades, informações de progressão serão mostradas.",
  str_help_uibreakcontroller_details5 = "1. Use uma quantidade específica de Cristais de Solamber para resgatar Solamber de 5 estrelas; Solamber Druse para resgatar Solamber de 6 estrelas (excluindo Solamber Auroriano exclusivo); Selos Solamber para resgatar Solamber Auroriano exclusivo.\n2. Isso não se aplica aos seguintes Aurorianos: Tohru, Kanna, Elma, Lucoa, Joker, Queen, Fox, Violet, Mona.",
  str_help_uiaircraftcontorller_explain = "Inf.: Colossus",
  str_help_uiaircraftcontorller_title1 = "Inf.: Custo de Lúmina da Col.",
  str_help_uiaircraftcontorller_title2 = "Inf.: Melhorar Lúmina da Col.",
  str_help_uiaircraftcontorller_title3 = "Inf.: Recursos da Colossus",
  str_help_uiaircraftcontorller_title4 = "Inf.: Lançamento da Colossus",
  str_help_uiaircraftcontorller_title5 = "Inf.: Interação da Colossus",
  str_help_uiaircraftcontorller_details1 = "1. Todas as salas na Colossus exigem Lúmina para funcionar.\n2. Desbloquear e melhorar o acesso de salas exige mais Lúmina.",
  str_help_uiaircraftcontorller_details2 = "Desbloquear e melhorar mais Salas Lúmina aumentará o limite de Lúmina.",
  str_help_uiaircraftcontorller_details3 = "Algumas salas na Colossus podem gerar recursos, que precisam ser retirados manualmente.",
  str_help_uiaircraftcontorller_details4 = "1. Todos os Aurorians têm Habilidades de Trabalho e quando atribuídos à sala correspondente, conseguem melhorar a função da sala, até certo ponto.\n2. Assim que um Aurorian atinge certas condições, novas Habilidades de Trabalho ou uma melhoria da Habilidade de Trabalho atual serão desbloqueadas.",
  str_help_uiaircraftcontorller_details5 = "1. Há quatro salas de lazer para relaxamento e diversão, na Colossus. Aurorians podem usar qualquer uma dessas quatro salas fazendo o que gostam.\n2. Toque em um Aurorian para interagir com ele.",
  str_help_uiaircraftcentralroom_explain = "Inf.: Ponte da Col.",
  str_help_uiaircraftcentralroom_title1 = "Inf.: Ponte",
  str_help_uiaircraftcentralroom_details1 = "1. Aumentar o Nível da Ponte aumentará o Ânimo Máx. da Colossus.\n2. Atribuir Aurorians pode aumentar os pontos de Ânimo gerados pela mobília.",
  str_help_uiaircraftpowerroom_explain = "Inf.: Sala Lúmina da Col.",
  str_help_uiaircraftpowerroom_title1 = "Inf.: Sala Lúmina",
  str_help_uiaircraftpowerroom_details1 = "1. A Sala Lúmina fornece Lúmina para as salas, e melhorar a sala aumenta a Lúmina.\n2. A Sala Lúmina pode aumentar a velocidade de recuperação de Vaga-lumes.\n3. Melhorar a sala e atribuir Aurorians pode aumentar ainda mais a velocidade de recuperação de Vaga-lumes.",
  str_help_uiaircraftmazeroom_explain = "Inf.: Posto de Exploração Colossus",
  str_help_uiaircraftmazeroom_title1 = "Inf.: Posto de Exploração",
  str_help_uiaircraftmazeroom_title2 = "Aum. a Saída do Território Secreto:",
  str_help_uiaircraftmazeroom_details1 = "1. Pode recuperar e armazenar MS.\n2. O tempo de restauração do MS armazenado será sincronizado com o do Território Secreto.\n3. Atribua Aurorians para acelerar a recuperação de MS.",
  str_help_uiaircraftmazeroom_details2 = "1. Exploração pode aumentar o número de Fragmentos de Texto gerados pelo Território Secreto.\n2. Melhorar essa sala desbloqueia mais estágios de Território Secreto, que podem ser concluídos por recompensas melhores.",
  str_help_uiaircraftresourceroom_explain = "Inf.: Est. de Recursos Colossus",
  str_help_uiaircraftresourceroom_title1 = "Inf.: Est. de Recursos",
  str_help_uiaircraftresourceroom_title2 = "Inf.: Recup. de Transp.",
  str_help_uiaircraftresourceroom_details1 = "1. Desbloqueia Recursos de Incursão.\n2. Recupera Transportes.\n3. Armazena Transportes.\n4. Melhorar a sala ou atribuir Aurorians aumenta a taxa de recuperação de Transportes.",
  str_help_uiaircraftresourceroom_details2 = "Ao alcançar o limite máximo de armazenamento, o Transporte não recuperará mais.",
  str_help_uiaircraftprismroom_explain = "Inf.: Pilar Prisma Colossus",
  str_help_uiaircraftprismroom_title1 = "Inf.: Pilar Prisma",
  str_help_uiaircraftprismroom_details1 = "1. O Pilar Prisma gera Prisma automaticamente.\n2. O Pilar Prisma pode guardar Prisma.\n3. Pilares Prisma de alto nível podem aumentar sua capacidade máxima de Prisma.\n4. Melhorar essa sala e atribuir Aurorians pode aumentar a taxa de geração de Prisma.",
  str_help_uiaircrafttowerroom_explain = "Inf.: Câmara Estelar Colossus",
  str_help_uiaircrafttowerroom_title1 = "Inf.: Câmara Estelar",
  str_help_uiaircrafttowerroom_details1 = "1. Pode produzir e guardar Pedras Coração.\n2. Câmaras Estelares de alto nível têm chance de produzir Joias Estelares adicionais.\n3. Melhorar essa sala ou atribuir Aurorians acelera a produção de Pedras Coração.",
  str_help_uiaircraftsmeltroom_explain = "Inf.: Oficina Colossus",
  str_help_uiaircraftsmeltroom_title1 = "Inf.: Fundição",
  str_help_uiaircraftsmeltroom_title2 = "Inf.: Oficina",
  str_help_uiaircraftsmeltroom_details1 = "1. Reagentes Atômicos podem ser usados para converter materiais do mesmo nível ou para fundir itens avançados via fundição.\n2. Colossus Patches podem ser desmontados para criar Fireflies.\n3. O Solamber excedente de um Auroriano no máximo Ruptura pode ser desmontado aqui.",
  str_help_uiaircraftsmeltroom_details2 = "1. Você pode criar e guardar Reagentes Atômicos aqui.\n2. Melhorar a Oficina aumenta o armazenamento de Reagentes Atômicos e desbloqueia mais materiais avançados.\n3. Aurorians atribuídos podem reduzir o custo de Reagentes Atômicos.",
  str_help_dispatch_title1 = "Missões de Expedição",
  str_help_dispatch_details1 = "1. A Expedição recebe missões todo dia. O Navegador pode obter recompensas ao expedir um esquadrão de Aurorians para completar essas missões.",
  str_help_dispatch_title2 = "Inf.: Expedir",
  str_help_dispatch_details2 = "1. Expedir um esquadrão de Aurorians consumirá tentativas de expedição, que você recupera com o tempo.\n2. Atribuir Aurorians pode acelerar a taxa de recuperação de tentativas de expedição.\n3. Melhorar a sala para atribuir mais Aurorians ou aumentar a classificação de Missões de Expedição.",
  str_help_uidiscovery_explain = "Inf.: Mapa de Exp.",
  str_help_uidiscovery_title1 = "Batalhas Hist. Princ.",
  str_help_uidiscovery_title2 = "Recompensas de Exploração",
  str_help_uidiscovery_title3 = "Avaliação da Batalha",
  str_help_uidiscovery_title4 = "Inimigo(s)",
  str_help_uidiscovery_details1 = "Direcione Aurorians para explorar o mundo ao completar Batalhas da História Principal e conheça mais Aurorians explorando o mundo.",
  str_help_uidiscovery_details2 = "Ao completar uma Exploração, você pode ganhar vários suprimentos e recompensas. O departamento especial dará ao comandante vários tipos de recompensas, baseado na avaliação da batalha, incluindo recompensas de 3 Estrelas, recompensas de primeira conclusão e recompensas normais.",
  str_help_uidiscovery_details3 = "Cada estágio possui um objetivo de batalha correspondente. Conquistar os três objetivos de batalha ao mesmo tempo concederá a maior avaliação da batalha: 3 estrelas.",
  str_help_uidiscovery_details4 = "Na tela do estágio você pode ver os inimigos. É possível visualizar os inimigos do estágio e descobrir os elementos e a aparência dos monstros que enfrentará.",
  str_help_uidrawcardcontroller_explain = "Dados de Recrut.",
  str_help_uidrawcardcontroller_title1 = "Inf.: Recrut. Exclusivo de Iniciante",
  str_help_uidrawcardcontroller_title2 = "Inf. do Rec. de Tempo Limitado:",
  str_help_uidrawcardcontroller_title3 = "Inf. do Recrut. Principal",
  str_help_uidrawcardcontroller_title4 = "Inf.: Prévia Aurorian",
  str_help_uidrawcardcontroller_title5 = "Info de Recrut. Alternado:",
  str_help_uidrawcardcontroller_details1 = "Apenas Lumâmbar pode ser usado para recrutar no evento Recrutamento Exclusivo de Iniciante.",
  str_help_uidrawcardcontroller_details2 = "1. Recrutamento de tempo limitado custa Fulgores Estelares Especiais.\n2. Se não possuir Fulgores Estelares Especiais, você pode gastar Lumâmbar para obter mais.",
  str_help_uidrawcardcontroller_details3 = "1. Recrutamento principal exige Fulgores Estelares.\n2. Se não possuir Fulgores Estelares suficientes, você pode gastar Lumâmbar para obter mais.",
  str_help_uidrawcardcontroller_details4 = "Você pode visualizar atributos e habilidades de Aurorians que alcançaram o estágio final da Ascensão, ao tocar no avatar do Aurorian ou na barra de informação exibindo seu nome.",
  str_help_uidrawcardcontroller_details5 = "1. O Recrutamento Rotativo requer Fulgores Estelares.\n2. Se não tiver Fulgores Estelares suficientes, você pode gastar Lumâmbar para obter mais.",
  str_help_helppet_title1 = "Inf.: Guia de Sup.",
  str_help_helppet_details1 = "1. Você pode configurar 1 Aurorian de Suporte para cada elemento, até 4 Aurorians.\n2. Aurorians de Suporte podem ser recrutados temporariamente por seus amigos. Isso não impede que você os envie para suas batalhas.",
  str_help_helppet_title2 = "Aurorians de Sup.:",
  str_help_helppet_details2 = "1. Você pode recrutar temporariamente Aurorians de Suporte de amigos ou um Aurorian de Suporte designado aleatoriamente pelo jogo para ajudar você em batalhas.\n2. Após Aurorians de Suporte serem atribuídos a sua formação, eles lutam como os seus próprios Aurorians.",
  str_help_helppet_title3 = "Restrições de Aur. de Suporte",
  str_help_helppet_details3 = "1. Aurorians de Suporte podem ser atribuídos apenas uma vez ao dia. Não há limite de quantos Aurorians diferentes você pode atribuir.\n2. As tentativas só são consumidas ao concluir um estágio. Perdas ou desistências não contam como tentativas.",
  str_help_petequip_title1 = "Dados de Equip. de Aurorian",
  str_help_petequip_details1 = "1. Quando um Aurorian alcança Ascensão I, o equipamento Aurorian é desbloqueado.\n2. Equipamento Aurorian pode aumentar o ATQ, a DEF, o PV e o dano de elemento eficaz de um Aurorian.\n3. Após desbloquear equipamentos, Aurorians receberão Habilidades de Equipamento. Aprimorar equipamento melhora o efeito dessas habilidades.",
  str_help_petequip_title2 = "Dano de Elemento Eficaz",
  str_help_petequip_details2 = "1. o dano de elemento eficaz base de um Aurorian é 120%, o que indica que ele causa 120% de dano a inimigos com elementos eficazes. Melhorar o equipamento aumentará o dano de elemento eficaz principal de um Aurorian.\n2. Quando os elementos de um Aurorian são ineficazes, o dano causado é de 80%.",
  str_help_petequip_title3 = "Informação de Refinamento de Equipamento",
  str_help_petequip_details3 = "1.Alguns equipamentos dos aurorianos podem ser melhorados. Isso é conhecido como Refinamento de Equipamento.\n2. O refinamento do equipamento é desbloqueado para esses aurorianos quando eles atingem a Ascensão III, Lv.80 e o Equipamento Lv.10.\n3. Atualizar o nível de refinamento do equipamento aumenta o ATK, DEF, HP e vários efeitos de habilidades de batalha do Aurorian.",
  str_help_talepettask_title1 = "Obtendo Aurorians Lendários",
  str_help_talepettask_details1 = "1. Escolha um dos Aurorianos Lendários para recrutar. Uma série de missões de recrutamento para o Auroriano selecionado será mostrada. Depois de completar todas as missões, você pode obter o Auroriano.\n2. Quando você obtiver seu Auroriano Lendário, ele será automaticamente atualizado para Ascensão III.",
  str_help_talepettask_title2 = "Recrutando Aurorians Lendários",
  str_help_talepettask_details2 = "1. Apenas um Aurorian Lendário pode ser invocado ao mesmo tempo e o progresso será contado para o recrutamento do Aurorian Lendário selecionado. O progresso da missão de recrutamento dos outros Aurorians será trancado ao recrutar um Aurorian Lendário específico.\n2. Trocar o Aurorian Lendário sendo recrutado, limpará o progresso do estágio mais alto da missão atual, mas estágios de missão concluídos não serão apagados. Preste atenção ao trocar!",
  str_help_talepetlevel_title1 = "Elísio",
  str_help_talepetlevel_details1 = "1. Em batalhas do Elísio, Aurorians serão melhorados com Poder Estelar, concedendo um poder maior que o normal.",
  str_help_talepetlevel_title2 = "Apex",
  str_help_talepetlevel_details2 = "1. Obtenha Regal, Frostfire, Mythos e Requiem para desbloquear a Memoria, Apex.",
  str_help_eve_title1 = "O Evento Começou!",
  str_help_eve_title2 = "Recomp. do Evento",
  str_help_eve_details1 = "Estágios de evento são divididos em dois estágios e desbloquearão nos momentos correspondentes.",
  str_help_eve_details2 = "Você pode ganhar Emblemas de Chave Inglesa nos estágios de evento, que podem ser trocados por itens na Loja da Rodovia.\nApós o término do evento, os emblemas excedentes serão convertidos em Noitium, de acordo com a taxa de troca da loja.\nVocê receberá recompensas de acordo com seu progresso de conclusão de missões de evento acumulado.",
  str_help_sakura_title1 = "Inf. do Grande Daruma",
  str_help_sakura_details1 = "1. Cinco conjuntos de prêmios estarão disponíveis no evento, com até 100 extrações em cada um.\n2. Gaste Pétala de Nuvescer para extrair prêmios.\n3. Você pode desbloquear o próximo conjunto ao extrair o grande prêmio do conjunto atual, mas ainda poderá extrair dos conjuntos de prêmios anteriores.\n4. Após o término do Grande Daruma, suas Pétalas de Nuvescer excedentes serão convertidas em Noitium na proporção de 1:30.",
  str_help_talepettask_title3 = "Avanço de Aurorian Lendário",
  str_help_talepettask_details3 = "1. Avanços de Aurorian lendários requerem Pedras Coração e Brasões de Estrela. Os avanços podem ser divididos em seis estágios. Brasões de Estrela consumidos por estágio: 1, 1, 2, 1, 2 e 3.\n2. Você pode obter Brasões de Estrela na Loja Estrela e em eventos futuros.",
  str_help_battlepass_tittle1 = "Livro do Evento Especial",
  str_help_battlepass_tittle2 = "Nível e Tempo",
  str_help_battlepass_tittle3 = "Edição Elite",
  str_help_battlepass_details1 = "Um livro de evento especial contendo uma variedade de missões e recompensas. Você pode ganhar pontos de Contribuição ao completar as missões neste livro de evento, aumentando o nível do livro e obtendo recompensas ao acumular pontos de Contribuição.",
  str_help_battlepass_details2 = "1. O Livro de Evento Especial possui um limite de nível. Assim que o nível máximo for alcançado, ele não poderá mais ser aumentado.\n2. O Livro de Evento Especial também possui um limite de tempo. Quando o tempo acabar, o Livro de Evento Especial será fechado.",
  str_help_battlepass_details3 = "1. O Livro de Evento Especial é desbloqueado por padrão e você pode resgatar suas recompensas baseado no nível dele.\n2. Compre a Edição Elite ou Edição de Luxo do Livro de Evento Especial. Você poderá resgatar a recompensa elite dos níveis correspondentes.",
  str_help_summerminigame_tittle = "Inf. do Evento",
  str_help_summerminigame_tittle1 = "Faça Bebida Gelada",
  str_help_summerminigame_tittle2 = "Humor do Cliente",
  str_help_summerminigame_tittle3 = "Bônus de Avaliação",
  str_help_summerminigame_tittle4 = "Calafrio Thrill",
  str_help_summerminigame_details1 = "1. A barraca de bebidas geladas já está funcionando! Quanto mais pedidos você completar dentro do tempo, mais pontos de avaliação você receberá.\n2. Você precisa completar 4 passos para fazer um copo de bebida gelada: selecionar o tamanho, ingredientes, bebidas e servir para o cliente. A ordem que você escolhe os ingredientes e as bebidas não importa.",
  str_help_summerminigame_details2 = "Cada cliente possui um tempo de espera. Conforme o tempo de espera aumenta, o humor dele cairá de Feliz para Impaciente e Bravo.\nQuanto melhor o humor do cliente, mais pontos de avaliação você receberá ao completar o pedido.",
  str_help_summerminigame_details3 = "Em um único desafio, quanto mais pedidos completar em sequência, maior seu bônus de avaliação será quando concluí-lo.",
  str_help_summerminigame_details4 = "Completar um certo número de pedidos em sequência ativará o Chill Thrill. Enquanto o Chill Thrill estiver ativo, você pode tocar em qualquer lugar na tela para completar automaticamente cada passo do pedido e acumular pontos de avaliação rapidamente!",
  str_help_summer_activity_two_title1 = "Inf: Desb. Fim de jogo",
  str_help_summer_activity_two_title2 = "Inf: Est. de Fim de jogo",
  str_help_summer_activity_two_details1 = "1. Assim que o evento começar, um conjunto de desafios de Fim de jogo será desbloqueado por dia.\n2. Os quatro estágios iniciais são níveis normais, enquanto o quinto será um estágio Fim de jogo.\n3. O último estágio Fim de jogo, O Monarca Desolado, é desbloqueado no sexto dia.",
  str_help_summer_activity_two_details2 = "1. Desafios Fim de Jogo podem ser repetidos.\n2. Você pode escolher a dificuldade e Modos Fim de Jogo desses estágios.\n3. Você pode ganhar Pontos de Fim de Jogo e receberá pontos bônus ao alcançar um novo recorde.",
  str_help_summer_activity_two_title3 = "Inf: Dificuldade",
  str_help_summer_activity_two_details3 = "1. Você pode escolher a dificuldade e Modos Fim de Jogo de cada estágio Fim de Jogo.\n2. Cada dificuldade concede uma quantidade de pontos base correspondente. Quanto maior a dificuldade, mais pontos.\n3. Cada Estratégia Fim de Jogo possui um multiplicador de pontos correspondente. Quanto mais Modos Fim de Jogo você selecionar, maior será seu multiplicador. O multiplicador de pontos base é 100%.\n4. Pontos de Fim de Jogo totais = Pontos Base x Multiplicador de Pontos.",
  str_help_world_boss_title1 = "Modo Códice Desolação",
  str_help_world_boss_details1 = "1. No modo Desolation Codex, você pode desafiar um chefe inimigo diferente a cada ciclo de evento. Os chefes têm HP infinito e você ganhará uma classificação e recompensas correspondentes de acordo com o dano causado.\n2.Você será promovido do nível Bronze para Paragon com base no seu maior dano total causado. Quando seu dano atual atingir um certo valor, você ganhará acesso ao nível Paragon. Depois de alcançar o Paragon, se você estiver entre os 999 melhores jogadores com os maiores resultados de desafio, será promovido ao nível Lendário.\n3. Sussurros Esquecidos e Declarações Esquecidas obtidos do Desolation Codex podem ser trocados por itens raros no Exiled Harborage.",
  str_help_world_boss_title2 = "Form. da Cruzada",
  str_help_world_boss_details2 = "1.Você pode usar várias equipes para desafiar os chefes. O dano total causado por todas as suas equipes será calculado como seu dano final causado.\n2.Cada auroriano pode ser implantado em apenas uma equipe. Se quiser atribuí-los a outra equipe, você pode optar por redefinir o registro de batalha da equipe atual.",
  str_help_world_boss_title3 = "Resultados da Class.",
  str_help_world_boss_details3 = "1. Cada ciclo do Desolation Codex dura por um período de tempo especificado. No final do ciclo atual, os resultados serão calculados de acordo com sua classificação naquele momento, e emblemas de classificação e recompensas serão emitidos correspondente.2. Seu emblema de classificação será exibido em seu avatar pessoal, e seu emblema para este ciclo será determinado de acordo com sua classificação no final do ciclo anterior. Se você não participar do desafio Desolation Codex neste ciclo, não receberá uma classificação no próximo ciclo e seu emblema não será exibido em seu avatar.\n3. As recompensas de classificação serão enviadas para sua caixa de correio. Por favor, note que o processo de entrega pode ser atrasado.",
  str_help_world_boss_title4 = "Info Inimigo",
  str_help_world_boss_details4 = "1. Após causar uma certa quantidade de dano a um chefe, os atributos do chefe serão aprimorados. Os chefes têm vários estágios de aprimoramento.\n2. Os resultados da batalha registrarão o dano causado apenas ao chefe, e o dano causado aos inimigos convocados pelo chefe não será incluído nos cálculos.\n3. Aurorianos causam 100% a mais de dano de contra-ataque elemental.\n4. Os inimigos do chefe são imunes a danos baseados em porcentagem de HP.",
  str_help_shuoming_aircrafttactic_help_title1 = "Info. Sala de Simulação",
  str_help_shuoming_aircrafttactic_help_desc1 = "1. A Sala de Simulação é onde os Discos de Dados são compilados e armazenados. Os Discos são criados gratuitamente toda semana.\n2. Você pode aprimorar a sala para aumentar a capacidade de armazenamento dos Discos e reduzir o tempo de criação.\n3. Você pode atribuir Aurorians aqui para reduzir mais ainda o tempo de criação de Discos.",
  str_help_shuoming_aircrafttactic_help_title2 = "Inf. Dsc. de D.:",
  str_help_shuoming_aircrafttactic_help_desc2 = "1. Quando um Disco de Dados é criado com sucesso, você receberá um Disco de Dados fechado. Toque para abri-lo, e ele se tornará um Disco de Dados de um tipo específico.\n2. Você pode acelerar a criação de Discos de Dados. Quando possuir chances grátis, Discos podem ser fabricados de graça. Além disso, você pode usar Vaga-lumes para reduzir o tempo de criação. Use Vaga-lumes suficientes para criar diretamente um novo Disco de Dados.\n3. Há um limite para o número de Discos de Dados que você pode ter. Se atingir o limite, não receberá mais discos. Depois de usar os discos de dados, você pode continuar obtendo outros quando o número total que você possuir estiver abaixo do limite.\n4. Discos de Dados podem ser apagados manualmente, mas não podem ser recuperados depois disso.",
  str_help_shuoming_aircrafttactic_help_title3 = "Inf. de Jogo dos Arquivos do Comando:",
  str_help_shuoming_aircrafttactic_help_desc3 = "1. No simulador de comando, você pode selecionar diferentes tipos de Discos de Dados para desafiar, e cada tipo de Disco de Dados corresponde a um cenário de combate.\n2. Esses cenários apresentam várias situações de combate, e as batalhas que já foram encontradas também têm uma chance de reaparecer.\n3. Em cada tipo de Disco de Dados, você pode escolher entre três dificuldades diferentes. Quanto maior a dificuldade, mais EXP de Comandante você receberá após concluir.\n4. Os Discos de Dados serão consumidos após concluir os estágios, mas não serão consumidos se um estágio não for concluído ou se você for derrotado.",
  str_help_shuoming_aircrafttactic_help_title4 = "Inf. Nv. de Comandante:",
  str_help_shuoming_aircrafttactic_help_desc4 = "1. EXP de Comandante pode ser obtido ao concluir qualquer Disco de Dados.\n2. Seu Nível de Comandante aumentará automaticamente após você acumular uma quantidade específica de EXP de Comandante.\n3. Após aumentar seu Nível de Comandante, você receberá as recompensas correspondentes.\n4. Você pode verificar seu Nível de Comandante nos Dados Pessoais e Dados de Amigos.",
  str_help_shuoming_aircrafttactic_help_title5 = "Info. Frag. de Dados:",
  str_help_shuoming_aircrafttactic_help_desc5 = "1. Quando um Disco de Dados é criado, há uma chance de você obter um disco que contém Fragmentos de Dados. Você pode obter Fragmentos após concluir qualquer dificuldade.\n2. Fragmentos de Dados serão exibidos como drops especiais.\n3. Quando todos os dados forem desbloqueados no banco de dados, Fragmentos de Dados não serão mais obtidos ao criar Discos de Dados.",
  str_help_shuoming_aircrafttactic_help_title6 = "Inf. B. de Dados",
  str_help_shuoming_aircrafttactic_help_desc6 = "1. Existem 4 dicas para cada tipo de informação no banco de dados.\n2. Ao consumir Fragmentos de Dados, você pode desbloquear as pistas no banco de dados e obter informações.\n3. Após desbloquear todas as 4 peças de informações no bando de dados, você vai obter as recompensas.\n4. Informações do banco de dados só podem ser desbloqueados na ordem correta. Após a interior ter sido completamente desbloqueada, a próxima informação ficará disponível para desbloqueio.",
  str_help_shuoming_n8_help_title1 = "Inf. de Jogo dos Arq. do Comando (Versão de Teste):",
  str_help_shuoming_n8_help_desc1 = "1. Os Arquivos do Comando (versão de teste) compõem um simulador de comando estratégico reparado temporariamente por Gronru.\n2. No simulador de comando, você pode selecionar diferentes tipos de Discos de Dados para desafiar, e cada tipo de Disco de Dados corresponde a um cenário de combate.\n3. Esses cenários apresentam várias situações de combate, e as batalhas que já foram encontradas também têm uma chance de reaparecer.\n4. Em cada tipo de Disco de Dados, você pode escolher entre três dificuldades diferentes. Quanto maior a dificuldade, mais Fama você receberá após concluir.\n5. Os Discos de Dados serão consumidos após concluir os estágios, mas não serão consumidos se um estágio não for concluído ou se você for derrotado.",
  str_help_shuoming_n8_help_title2 = "Obtendo Dsc. de Dados:",
  str_help_shuoming_n8_help_desc2 = "Informações de Aquisição de Disco de Dados\n1. Você receberá alguns discos de dados no início do evento.\n2. Após o início do evento, você receberá discos de dados em intervalos regulares.\n3. Há um limite para o número de Discos de Dados que você pode ter. Se atingir o limite, não receberá mais Discos. Depois de consumir os Discos de Dados, reduzindo sua quantidade total abaixo do limite, você continuará a obtê-los.\n4. Os Discos de Dados podem ser excluídos manualmente, mas não podem ser recuperados depois de fazer isso.",
  str_help_data_title = "Inf. B. de Dados",
  str_help_data_desc = "1. Existem 4 dicas para cada tipo de informação no banco de dados.\n2. Ao consumir Fragmentos de Dados, você pode desbloquear as pistas no banco de dados e obter informações.\n3. Após desbloquear todas as 4 peças de informações no bando de dados, você vai obter as recompensas.\n4. Informações do banco de dados só podem ser desbloqueados na ordem correta. Após a interior ter sido completamente desbloqueada, a próxima informação ficará disponível para desbloqueio.",
  str_help_shuoming_blackunderbellydungeon_help_title1 = "Noite Branca, Informações do Baixo-ventre Negro",
  str_help_shuoming_blackunderbellydungeon_help_desc1 = "1. Quando os estágios White Night, Black Underbelly forem concluídos um certo número de vezes, um Bonus Time será ativado, onde haverá Eclipsites Corrompidos no campo de batalha. Derrote-os para ganhar Nightium extra.\n2.Estágios concluídos em diferentes níveis de dificuldade em White Night, Black Underbelly são registrados separadamente.\n3.As etapas serão contadas separadamente quando os Transportadores forem usados para varrer.",
  str_help_shuoming_fengxinta_title = "Informações da Torre Jacinto",
  str_help_shuoming_fengxinta_desc = "1. Uma vez que você obtenha móveis ou projetos de construção, a produção de itens correspondentes pode ser desbloqueada em Hyacinth Tower.\n2. A produção consome determinados materiais. Quando a produção estiver concluída, você poderá reivindicar o item.\n3. Aumente o nível do Cloud Gardens para desbloquear mais filas de produção e aumentar a produtividade.",
  str_help_shuoming_baifang_title1 = "Visita de Amigos",
  str_help_shuoming_baifang_desc1 = "1. Quando um amigo tem Cloud Gardens, você pode visitá-lo.\n2. Ao visitar os Jardins de Nuvem de um amigo, você pode realizar ações como acelerar as produções de um amigo, regar Árvores Únicas e pegar itens da Caixa de Itens do seu amigo.",
  str_help_shuoming_baifang_title2 = "Aceleração da Produção e Rega",
  str_help_shuoming_baifang_desc2 = "1. Quando houver um item ou uma Árvore Única que possa ser acelerada nos Jardins Nuvens de um amigo, lembre-se de acelerá-los ou regá-los!\n2. Cada item em produção só pode ser acelerado uma vez por dia.\n3. Cada parcela de Terra da Fertilidade só pode ser regada uma vez por dia.",
  str_help_shuoming_baifang_title3 = "Caixa de itens do Cloud Gardens",
  str_help_shuoming_baifang_desc3 = "1. Os navegadores podem colocar itens na caixa de itens do Cloud Gardens.\n2. Ao visitar os Jardins de Nuvem de um amigo, os Navegadores podem pegar itens de uma grade na Caixa de Itens de seu amigo.\n3. Os navegadores só podem pegar itens uma vez por dia de cada amigo.\n4. Os navegadores podem levar itens até 10 vezes por dia.",
  str_help_shuoming_homelevel_title1 = "Decoração de Jardins de Nuvem",
  str_help_shuoming_homelevel_desc1 = "1. Os navegadores podem decorar Cloud Gardens com edifícios e árvores únicas.\n2. Enquanto um Auroriano convidado estiver hospedado no Cloud Gardens, sua Afinidade aumentará com o tempo.",
  str_help_shuoming_homelevel_title2 = "Construindo Edifícios",
  str_help_shuoming_homelevel_desc2 = "Vários edifícios podem ser construídos através da Hyacinth Tower localizada no centro da praça para decorar Cloud Gardens.\nMadeira e minérios são necessários para construir edifícios. Eles estão espalhados por toda a área e podem ser obtidos com as ferramentas apropriadas.",
  str_help_shuoming_homelevel_title3 = "Criação de árvores únicas",
  str_help_shuoming_homelevel_desc3 = "As Árvores Únicas são árvores decorativas que podem ser colocadas nos Jardins das Nuvens.\nÁrvores únicas podem ser plantadas plantando suas sementes no Land of Fertility, que pode ser obtido na Hyacinth Tower.",
  str_help_shuoming_homelevel_title4 = "pescaria",
  str_help_shuoming_homelevel_desc4 = "Uma variedade de peixes pode ser pescada ao longo do rio.\nAlguns peixes valem mais e podem ser vendidos para atender aos pedidos da loja.\nAlguns peixes raros são ótimos para exibição e podem ser criados na Fonte da Esperança da praça.",
  str_help_shuoming_homelevel_title5 = "Caça ao Tesouro",
  str_help_shuoming_homelevel_desc5 = "Caçar tesouros em Cloud Gardens dá a chance de obter Baús e Hope Coins.\nOs navegadores podem jogar Hope Coins na Fonte da Esperança para aprender a história por trás delas.",
  str_help_shuoming_homelevel_title6 = "Aurorianos acomodados",
  str_help_shuoming_homelevel_desc6 = "Depois de construir e decorar o dormitório dos jardins, os navegadores podem convidar os aurorianos para se mudarem.\nSempre que um auroriano se muda para Cloud Gardens, os navegadores podem interagir com eles e desencadear eventos aleatórios.",
  str_help_shuoming_homelevel_title7 = "Visitando amigos",
  str_help_shuoming_homelevel_desc7 = "Os navegadores podem visitar os Jardins de Nuvem de seus amigos para ajudar a acelerar a construção de edifícios e o crescimento da Árvore Única.\nOs navegadores também podem colocar itens na caixa de itens do Cloud Gardens para os amigos visitantes.",
  str_help_shuoming_breed_desc1 = "Criação de Mutação, Criação Direcionada e Criação de Alteração podem ser realizadas na Terra da Fertilidade.\nAdicione sementes de árvores únicas aqui para iniciar a reprodução. Após procriar por um período de tempo, você receberá uma Árvore Única e a semente desta Árvore Única. O número de sementes cai aleatoriamente dentro de um determinado intervalo.\nÁrvores Únicas podem ser colocadas em Cloud Gardens, onde podem ser submetidas a reprodução de corantes.",
  str_help_shuoming_breed_desc2 = "A criação de mutações só pode ser realizada com sementes diferentes da mesma raridade. Criação de Mutação não pode ser realizada em Árvores Únicas de raridade premium.\nSe as duas sementes forem da mesma categoria, a Árvore Única produzida será da mesma categoria.\nSe as duas sementes forem de categorias diferentes, qualquer árvore correspondente sob as duas categorias pode ser produzida, e há uma grande chance de produzir uma Árvore Única pertencente ao gênero Semente Principal.",
  str_help_shuoming_breed_desc3 = "Criação de Mutação tem a chance de produzir Árvores Únicas aleatórias de maior raridade. Árvores Únicas Avançadas serão produzidas aleatoriamente a partir de todas as árvores nas categorias representadas pela Semente Principal e pelo Fator de Mutação.\nSe a atualização não for bem sucedida, a Semente Principal ou a Árvore Única correspondente ao Fator de Mutação será produzida.",
  str_help_shuoming_breed_desc4 = "Os resultados do Mutation Breeding podem ser visualizados após adicionar a Semente Principal e o Fator de Mutação.",
  str_help_shuoming_breed_desc5 = "A reprodução direcionada só pode ser realizada com duas sementes idênticas. A Criação Direcionada sempre produzirá uma Árvore Única correspondente à semente adicionada.",
  str_help_shuoming_breed_desc6 = "Aproximar-se de uma árvore única que foi colocada no Cloud Gardens fará com que a árvore passe por um processo de tingimento. Este processo usará Cristalóides de Rosa e mudará a cor da Árvore Única.",
  str_help_shuoming_breed_desc7 = "A criação de mutações e a criação direcionada gerarão itens de bônus: Petrowood.\nO rendimento da Petrowood está relacionado com a qualidade das Unique Trees, e o limite semanal é de 100.",
  str_help_shuoming_breed_desc8 = "Consumir 1 Árvore Única IV e 1 Poção de Alteração em Procriação de Alteração pode gerar outras Árvores Únicas IV básicas da mesma espécie.",
  str_help_shuoming_breed_title1 = "A terra da fertilidade e das árvores únicas",
  str_help_shuoming_breed_title2 = "Regras de reprodução de mutações",
  str_help_shuoming_breed_title3 = "Regras de atualização",
  str_help_shuoming_breed_title4 = "Visualização do resultado da reprodução",
  str_help_shuoming_breed_title5 = "Regras de reprodução direcionada",
  str_help_shuoming_breed_title6 = "Criação de corantes",
  str_help_shuoming_breed_title7 = "Petrowood",
  str_help_shuoming_breed_title8 = "Alteração das regras de reprodução",
  str_help_homeland_wishing_title1 = "Informações da Fonte da Esperança",
  str_help_homeland_wishing_title2 = "Coletando moedas de esperança",
  str_help_homeland_wishing_title3 = "Criação de peixes ornamentais",
  str_help_homeland_wishing_desc1 = "1. Diz-se que os celestitas têm uma tradição não oficial. Quando um celestita está prestes a se tornar adulto, ele precisa jogar uma moeda da esperança que eles fizeram pessoalmente na fonte da esperança e fazer um pedido. Esta tradição foi esquecida com o desaparecimento dos Caelestites, e até suas Hope Coins desapareceram sem deixar vestígios...\n2. Há uma chance de obter Hope Coins ao pescar.",
  str_help_homeland_wishing_desc2 = "1. Moedas da Esperança que são obtidas nos Jardins das Nuvens podem ser jogadas na Fonte da Esperança para serem coletadas.\n2. Você receberá recompensas de acordo com o número de Hope Coins lançadas na Fonte da Esperança.",
  str_help_homeland_wishing_desc3 = "1. Peixes de alta qualidade que você pesca podem ser criados na Fonte da Esperança.\n2. Os peixes criados podem ser recolhidos a qualquer momento sem afetar suas vendas.",
  str_help_shuoming_visitfriends_title1 = "Informações da lista inicial",
  str_help_shuoming_visitfriends_title2 = "Informações da lista inicial 1",
  str_help_shuoming_visitfriends_title3 = "Informações da lista inicial 2",
  str_help_homeland_visitfriends_desc1 = "Descrição da lista inicial 1",
  str_help_homeland_visitfriends_desc2 = "Descrição da lista inicial 2",
  str_help_homeland_visitfriends_desc3 = "Descrição da lista inicial 3",
  str_help_shuoming_storehouse_title1 = "Informações da caixa de itens",
  str_help_shuoming_storehouse_title2 = "Informações da caixa de itens 1",
  str_help_shuoming_storehouse_title3 = "Informações da caixa de itens 2",
  str_help_homeland_storehouse_desc1 = "Descrição da caixa do item 1",
  str_help_homeland_storehouse_desc2 = "Descrição da caixa de itens 2",
  str_help_homeland_storehouse_desc3 = "Descrição da caixa de itens 3",
  str_help_diff_mission_title1 = "Caixa de Pandora",
  str_help_diff_mission_title2 = "Troféu do Desafio",
  str_help_diff_mission_title3 = "Formação do Desafio",
  str_help_diff_mission_title4 = "Car. do Campo de Batalha",
  str_help_diff_mission_title5 = "Info Inimigo",
  str_help_diff_mission_desc1 = "1. A Caixa de Pandora consiste em uma série de estágios altamente difíceis, fornecendo uma variedade de mecanismos e chefes para os Navegantes desafiarem.\n2. Cada capítulo da Caixa de Pandora contém vários pontos de passagem, e cada ponto de passagem contém vários estágios. Como não há ordem entre os estágios, os navegadores são livres para desafiar qualquer estágio dentro do waypoint.\n3. Existem de 3 a 5 troféus de desafio em cada waypoint, e somente usando a formação necessária de acordo com as condições do Troféu para limpar todos os estágios do waypoint os navegadores podem obter os troféus e recompensas correspondentes.\n4. Ao desafiar estágios no mesmo waypoint, os navegadores são obrigados a usar diferentes aurorianos.",
  str_help_diff_mission_desc2 = "1. Cada waypoint tem 3-5 troféus de desafio, e diferentes troféus de desafio têm diferentes condições de desafio.\n2. Os navegadores precisam limpar todas as etapas de waypoint com as formações necessárias de acordo com as condições do Troféu para obter os Troféus e recompensas correspondentes.\n3. Como não há ordem entre os Troféus, os Navegantes são livres para desafiar cada Troféu várias vezes.\n4. Uma vez obtido um Troféu de Desafio, ele permanecerá mesmo quando a formação do estágio for reiniciada.",
  str_help_diff_mission_desc3 = "1. Cada estágio pode ser desafiado com uma formação.\n2. Aurorianos usados não podem ser usados novamente em estágios diferentes no mesmo waypoint. No entanto, os Aurorianos podem ser usados novamente em outros waypoints.\n3. A formação do estágio pode ser redefinida, e redefinir a formação não afetará os Troféus de Desafio obtidos.",
  str_help_diff_mission_desc4 = "Cada estágio tem suas próprias características de campo de batalha que fornecem mecanismos diferentes para estágios e monstros. Os navegadores podem aprender sobre as características do campo de batalha na tela do palco para fazer a preparação necessária com antecedência.",
  str_help_diff_mission_desc5 = "Os navegadores podem ver informações inimigas na tela do palco e aprender sobre as características do campo de batalha no palco, como os elementos e a aparência dos monstros que você enfrentará.",
  str_help_shuoming_tanbao_title1 = "Recuperação de sinal",
  str_help_shuoming_tanbao_title2 = "Explorador Chubb",
  str_help_shuoming_tanbao_title3 = "Detector portátil",
  str_help_shuoming_tanbao_title4 = "Localize os tesouros",
  str_help_shuoming_tanbao_desc1 = "1. A Investigação Detalhada consome Sinal Especial ou Sinal Normal. 2. Após a Investigação Detalhada estar online, cada Navegador pode inicialmente receber o Sinal Especial ×1 e o Sinal Normal ×2. 3. A partir do segundo dia do evento, cada Navegador receberá Sinal Especial ×1 e Sinal Normal ×2 todos os dias. Cada Navegador pode receber até um sinal especial ×6 e um sinal normal ×12 no total durante o período do evento.",
  str_help_shuoming_tanbao_desc2 = "1. Após o início da Investigação Detalhada, o Explorador Chubb aparecerá ao redor de Hyacinth Square em Cloud Gardens.\n2. Localize o Explorer Chubb em Hyacinth Square e interaja com ele para começar a consumir Sinais para começar a investigar.\n3. Localize o tesouro usando a orientação do Sinal dentro do tempo determinado para concluir a investigação. Caso contrário, será considerado um fracasso.",
  str_help_shuoming_tanbao_desc3 = "1.Treasures estão espalhados por Cloud Gardens. Durante a investigação, os Navegadores podem escanear e localizar os tesouros com o Detector Portátil.\n2. O Detector Portátil emitirá cores diferentes com base na proximidade dos Navegadores do tesouro (de longe para perto): vermelho, amarelo e verde.\n3. O detector portátil também pode escanear a localização aproximada de tesouros. Ele fornecerá feedback por meio de ângulos de varredura com base em sua distância até o tesouro. Quanto mais perto você chegar, mais estreito será o ângulo de varredura, até que seja capaz de identificar a localização do tesouro.",
  str_help_shuoming_tanbao_desc4 = "1. Quando descoberto pelo Detector Portátil, o tesouro emitirá um brilho fraco. 2. Dependendo do tipo de sinal consumido pela detecção, a cor do brilho será diferente. 3. Quando o Navegador encontrar o tesouro, toque no tesouro e a vitória será sua! E você recebe a recompensa correspondente!",
  str_help_n20minigame_tittle1 = "Faça Udon",
  str_help_n20minigame_tittle2 = "Humor do Cliente",
  str_help_n20minigame_tittle3 = "Bônus de Avaliação",
  str_help_n20minigame_tittle4 = "Topo do Frenesi",
  str_help_n20minigame_details1 = "1. O carrinho de comida já está funcionando! Quanto mais pedidos você concluir dentro do limite de tempo, mais pontos de classificação você ganhará.\n2. Você precisará concluir 4 etapas para fazer uma porção de udon: selecione um tamanho, ingredientes, sopa e sirva ao cliente. A ordem em que você seleciona os ingredientes e a sopa não importa.",
  str_help_n20minigame_details2 = "Cada cliente possui um tempo de espera. Conforme o tempo de espera aumenta, o humor dele cairá de Feliz para Impaciente e Bravo.\nQuanto melhor o humor do cliente, mais pontos de avaliação você receberá ao completar o pedido.",
  str_help_n20minigame_details3 = "Em um único desafio, quanto mais pedidos completar em sequência, maior seu bônus de avaliação será quando concluí-lo.",
  str_help_n20minigame_details4 = "Completar um certo número de pedidos seguidos ativará o Topping Frenzy. Enquanto o Topping Frenzy estiver ativo, você pode tocar em qualquer lugar na tela para concluir automaticamente cada etapa do pedido e acumular pontos de classificação rapidamente!",
  str_help_activity_review_tittle1 = "Informações de Memórias de Viagem",
  str_help_activity_review_desc1 = "1. Você pode consumir Discos em Nuvem para desbloquear Memórias de Viagem.\n2. Você receberá 1 Cloud Disk quando atingir 60 Atividade todos os dias.\n3. Os Discos em Nuvem não se acumulam mais quando o limite é atingido.",
  str_help_sailing_explain = "Para o abismo",
  str_help_sailing_title1 = "Cidade Baixa π",
  str_help_sailing_title2 = "Ventilador",
  str_help_sailing_title3 = "Equipes de Exploração",
  str_help_sailing_title4 = "Contagens do Ventilador",
  str_help_sailing_details1 = "Um conjunto de ruínas descobertas pela Federação Illumina há cerca de três décadas. Depois de gastar uma grande quantidade de trabalho e recursos para reconstruí-la, a Federação começou a mergulhar nas profundezas aparentemente sem fundo da Cidade Baixa, na esperança de descobrir mais conhecimento da antiga civilização de Astra. Há dez anos, porém, as ruínas foram atacadas por uma legião de Eclipsites comandada pelo Eclipse. Depois de inundar os sistemas de ventilação da Cidade Baixa com gases tóxicos, onda após onda de Eclipsites assassinos começaram a inundar as ruínas, efetivamente parando a ambiciosa exploração da Federação Illumina. Diante de um fluxo interminável de monstros sedentos de sangue, a Federação não teve escolha a não ser lutar enquanto recuava para a superfície, isolando cada andar da Cidade Baixa ao longo do caminho. Como resultado, Undercity 101 foi declarada completamente fora dos limites e altamente perigosa, já que os inúmeros Eclipsites que a invadiram há uma década ainda vagam por seus andares hoje. Temendo que os segredos da antiga civilização caíssem nas mãos erradas, mais tarde foi renomeada Undercity π, uma Undercity sem fundo escondendo o conhecimento incalculável de eras passadas ...",
  str_help_sailing_details2 = "1. Cada andar em Undercity π tem um número não especificado de ventiladores. Começando no Piso 1, o Navegador deve localizar todos os ventiladores enquanto explora a Cidade Baixa.\n2. O Navegador deve ativar todos os ventiladores em cada andar da Cidade Baixa para limpar a fumaça tóxica e avançar para o próximo andar.\n3. Cada ventilador requer o Lumina de 5 Aurorianos para ativar. Os ventiladores podem ser ativados em qualquer ordem.\n4. Ao aumentar o número de \"Total de Ventiladores Ativados\", o Navegador pode reivindicar recompensas ainda maiores através da interface de Recompensas de Exploração!",
  str_help_sailing_details3 = "1. Cada andar contém vários ventiladores, cada um dos quais é guardado por um poderoso chefe Eclipsite. Como tal, uma equipe completa de 5 Aurorianos é necessária para desafiar cada etapa.\n2. Cada Auroriano só pode ser atribuído a uma única equipe no mesmo andar, e não pode ser atribuído a equipes de outros estágios do andar.\n3. A formação de palco pode ser reiniciada; Aurorianos cujas formações são redefinidas podem ser atribuídas a qualquer formação de palco no andar atual.\n4. As etapas que foram liberadas devem ser guarnecidas por uma equipe; redefinir a equipe de guarnição de um estágio redefinirá o status desse estágio de limpo para não liberado.\n5. Um andar é contado como liberado quando todas as suas etapas forem liberadas.\n6. Redefinir a formação da equipe de um estágio em um piso liberado não alterará o status desse piso.",
  str_help_sailing_details4 = "1. Ao longo de suas explorações, os ventiladores serão divididos em dois conjuntos: \"Ventiladores Ativados\" e \"Total de Ventiladores Ativados\".\n2. \"Total de Ventiladores Ativados\" indica o maior número de ventiladores ativados pelo Navigator para esta exploração; redefinir qualquer estágio/piso não afetará esse número.\n3. \"Ventiladores Ativados\" indica o número de ventiladores atualmente ativados para uma determinada tentativa de exploração. Redefinir um estágio para o andar atual diminuirá esse número; os estágios de redefinição para um piso limpo não afetarão esse número.",
  str_help_shuoming_property_cultivate_title1 = "Informações do Sistema de Iluminação",
  str_help_shuoming_property_cultivate_desc1 = "1. O sistema de Iluminação é um sistema de atualização que melhora as capacidades de combate de todos os Aurorians.\n2. O sistema de Iluminação é composto por um Módulo de Água, Fogo, Floresta e Trovão, e cada módulo aprimora os atributos dos Aurorians com o elemento primário correspondente.\n3. O sistema de Iluminação aumenta o ATQ, DEF, HP, Dano de Elemento Eficaz, Dano Final da Habilidade Ativa e Probabilidade de Atualização de Casas Elementais dos Aurorians do mesmo elemento.\n4. Os aprimoramentos do sistema de Iluminação não serão exibidos na interface, mas terão efeito direto nas batalhas.\n5. Os aprimoramentos do sistema de Iluminação não terão efeito em algumas jogabilidades. Consulte as informações relevantes da jogabilidade para obter detalhes.",
  str_help_shuoming_property_cultivate_title2 = "Informações de Atualização do Sistema de Iluminação",
  str_help_shuoming_property_cultivate_desc2 = "1. Materiais podem ser usados para aumentar o nível dos Módulos Elementares.\n2. Os Módulos Elementares podem ser aprimorados após atingirem seu nível máximo e as condições prévias serem cumpridas.\n3. Os Módulos Elementares podem ter seu nível aumentado ainda mais após serem aprimorados.",
  str_help_elimate_explain = "Informações do Treinamento Iluminado",
  str_help_elimate_tittle1 = "Info de Gameplay",
  str_help_elimate_tittle2 = "Laços Aurorianos",
  str_help_elimate_tittle3 = "Facção de Apoio",
  str_help_elimate_tittle4 = "Pontos de Recompensa",
  str_help_elimate_tittle5 = "Rec. de Conclusão",
  str_help_elimate_details1 = "1. Durante o Treinamento Iluminado, é possível desafiar vários níveis de dificuldade.\n2. Independentemente do nível de dificuldade, todos os desafios devem ser concluídos em um determinado número de rodadas, e a porcentagem de HP dos Aurorianos é herdada entre os estágios. O desafio termina se você for derrotado em qualquer estágio.\n3. Engrenagens de Iluminação, que são eficazes apenas no desafio atual, podem ser obtidas após a limpeza dos estágios. Todas as Engrenagens de Iluminação serão removidas após o término do desafio.4. Nas etapas de Treinamento Iluminado, não é necessário fazer conexões. Em vez disso, os ladrilhos podem ser removidos tocando neles. Tocar em um ladrilho também selecionará todos os ladrilhos adjacentes da mesma cor. Tocar no ladrilho novamente removerá os ladrilhos selecionados, e os Aurorianos lançarão um Chain Combo com base no número de ladrilhos removidos.",
  str_help_elimate_details2 = "1. Durante o Treinamento Iluminado, existem laços entre certos Aurorians.\n2. Quando Aurorians com um laço são implantados ao mesmo tempo, eles ganharão o elemento primário um do outro. Quando as casas de um desses elementos primários são removidas, ambos os Aurorians entrarão em combate.",
  str_help_elimate_details3 = "1. No Treinamento Iluminado, cada facção tem uma habilidade de suporte de facção única.\n2. Quando pelo menos 3 Aurorians da mesma facção são implantados, a remoção de 15/30 ladrilhos de uma vez acionará uma habilidade de facção Lv.1/Lv.2.",
  str_help_elimate_details4 = "1. Durante o Treinamento Iluminado, os pontos são ganhos ao limpar os estágios. Quanto maior a dificuldade, mais pontos obtidos ao limpar um estágio.\n2. As recompensas de pontos podem ser resgatadas quando um certo número de pontos é acumulado em cada período. As recompensas de pontos são resetadas em cada período.\n3. Quanto maior a dificuldade desbloqueada, melhores são as recompensas de pontos em cada período, e maior é o limite superior de recompensas de pontos.",
  str_help_elimate_details5 = "1. Durante o Treinamento Iluminado, as recompensas podem ser reivindicadas após a conclusão dos estágios.\n2. Durante cada período, a quantidade e o montante de recompensas de conclusão que podem ser reivindicadas são limitados, e esse limite é reiniciado em cada período.",
  str_help_world_boss_title1_new = "Códice da Desolação: Modo Iluminação",
  str_help_world_boss_details1_new = "1.No modo Desolation Codex, você pode desafiar um chefe inimigo diferente a cada ciclo de evento. Os chefes têm HP infinito, e você ganhará uma classificação e recompensas correspondentes de acordo com o dano que causar.\n2.Você será promovido do rank Bronze para Paragon com base no seu dano total mais alto causado. Quando o seu dano atual atingir uma certa quantidade, você ganhará acesso ao rank Paragon. 1. Após alcançar o Paragon, se você estiver entre os 999 jogadores com os melhores resultados no desafio, será promovido ao rank Lendário.\n2. Forgotten Whispers e Forgotten Utterances obtidos do Desolation Codex podem ser trocados por itens raros no Exiled Harborage.\n3. No Modo Iluminação, não é necessário fazer conexões. Em vez disso, as peças podem ser removidas tocando nelas. Tocar em uma peça também selecionará todas as peças adjacentes da mesma cor. Ao tocar no ladrilho novamente, os ladrilhos selecionados serão removidos e os Aurorianos lançarão um Combo em Cadeia com base no número de ladrilhos removidos.",
  str_help_season1_tab_1 = "Despertando na Tempestade",
