  str_help_season1_title_403 = "Detalhes do fragmento",
  str_help_season1_title_501 = "Caixa de coleta de Eve",
  str_help_season1_title_502 = "Tesouro sem nome",
  str_help_season1_title_503 = "Síntese de itens",
  str_help_season1_title_504 = "Marca das memórias",
  str_help_season1_title_505 = "memória sônica",
  str_help_season1_disc_101 = "O Despertar na Tempestade chegou. Num sono profundo, o sonho reaparece, repetindo-se.",
  str_help_season1_disc_102 = "Guie Eve na utilização de seus pontos de inteligência para conquistar o Presságio dentro do sonho. Ao resolvê-lo, você terá acesso à Metamorpha e aos Fragmentos de Sedimento. Estes podem ser trocados por várias recompensas na Oficina da Memória, incluindo o traje Era Uma Vez na Primavera.",
  str_help_season1_disc_103 = "Termine as missões detalhadas nos fragmentos de memória para ganhar Lumamber e descubra histórias ocultas sobre Eve.",
  str_help_season1_disc_104 = "Complete missões no mundo dos sonhos para adquirir o conjunto Stand By Me.",
  str_help_season1_disc_105 = "As bijuterias coletadas no Sonho são todas cuidadosamente guardadas aqui por Eve.",
  str_help_season1_disc_201 = "O Despertar na Tempestade está sobre nós, mas o Presságio está impedindo o despertar de Eva. Assistir Eve em vencer o Omen, e ser recompensado generosamente pelo sucesso. Observe que cada desafio contra o Omen consumirá 1 ponto de Wit.",
  str_help_season1_disc_202 = "Existem dois níveis de dificuldade para o desafio Omen: Reverie e Nightmare.\nEmbora Nightmare ofereça uma experiência mais desafiadora, também oferece recompensas superiores. Se você achar Nightmare muito opressor, considere tentar Reverie primeiro.\nDentro do mesmo desafio Omen, o nível de estrela alcançado em Nightmare será sincronizado com Reverie. Alcançar uma recompensa de liberação de três estrelas e a 1ª Recompensa Completa em Pesadelo também concederá a você as recompensas correspondentes de Reverie.",
  str_help_season1_disc_203 = "Visite os Detalhes do estágio para ver todas as informações do Presságio relacionadas a Awakening in the Storm, onde você também pode alternar entre Reverie e Nightmare.",
  str_help_season1_disc_204 = "Eve mantém um senso de racionalidade e clareza, permitindo que ela desafie o Presságio em Despertar na Tempestade. Os pontos de perspicácia serão repostos em 3 pontos todos os dias às 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season1_disc_205 = "Sorrisos Levam à Felicidade pode conceder buffs poderosos para Eve.\nTriunfe sobre o Presságio na dificuldade Pesadelo para obter Ondulações de Alegria. O item pode aumentar o nível de Sorrisos Levam à Felicidade.",
  str_help_season1_disc_206 = "Tesouros misteriosos estão escondidos em Cognova e Nostalix. Você pode colocá-los na Caixa de Coleta de Eve. Não perca a chance de abri-los.",
  str_help_season1_disc_207 = "A tempestade de areia bloqueou o caminho de Eve e nublou seu coração. Derrote o Presságio ao seu redor para dissipar a Tempestade de Areia!",
  str_help_season1_disc_208 = "Eve, sempre obediente, nunca teve o desejo de romper a ilusão. No entanto, aquilo que ela mais preza acaba por despedaçá-la. \"Deixe-me herdar a arma do meu irmão!\"",
  str_help_season1_disc_209 = "Uh-oh, um enxame de Devoradores de Sonhos está roendo o sonho de Eve! Se o sonho dela desmoronar, a pobre Eve pode nunca mais acordar... Não podemos deixar isso acontecer!\nDas 05:00 de 6 de setembro às 04:00 de 27 de setembro, um novo enxame de Devoradores de Sonhos surge às 05:00 diariamente. Você terá 5 chances de expulsá-los todos os dias, sendo que as 2 primeiras expulsões bem-sucedidas oferecem recompensas generosas. A dificuldade de expulsar esses Devoradores de Sonhos aumenta a cada tentativa até ser reiniciada às 05:00 do dia seguinte.",
  str_help_season1_disc_301 = "A Oficina da Memória oferece uma seleção de recompensas, entre as quais o traje Era uma primavera.",
  str_help_season1_disc_302 = "Resolva o Presságio no sonho para adquirir Metamorpha e Fragmentos de Sedimento.",
  str_help_season1_disc_303 = "Metamorpha pode ser trocada pelo traje Era Uma Vez na Primavera, e Fragmentos de Sedimento podem ser trocados por várias outras recompensas.",
  str_help_season1_disc_304 = "Após o fechamento da Oficina de Memórias, Metamorpha será convertido em Fragmentos de Sonho na proporção de 1:1, enquanto os Fragmentos de Sedimento serão trocados por Nightium na proporção de 1:30. Os itens correspondentes serão enviados diretamente para o seu Armazém após a conversão bem-sucedida.",
  str_help_season1_disc_305 = "Após o fechamento da Memory Workshop, o traje Once Upon a Springtime ainda estará disponível em Authentic Dreamscapes. Nesse momento, você poderá trocar Dream Shards, que são convertidos de Metamorpha, pelo traje.",
  str_help_season1_disc_401 = "Termine as missões detalhadas nos fragmentos de memória para ganhar Lumamber e descubra histórias ocultas sobre Eve.",
  str_help_season1_disc_402 = "Complete as missões específicas para desbloquear os fragmentos e adquirir Lumamber.",
  str_help_season1_disc_403 = "Ao desbloquear os fragmentos, você também pode descobrir histórias ocultas sobre Eve.",
  str_help_season1_disc_501 = "As bijuterias coletadas no Sonho são todas cuidadosamente guardadas aqui por Eve.",
  str_help_season1_disc_502 = "Tesouros Não Nomeados contêm itens colecionáveis encontrados no sonho, juntamente com pistas para adquirir conteúdo que ainda não foi coletado.",
  str_help_season1_disc_503 = "Alguns colecionáveis irão interagir magicamente uns com os outros, criando novos objetos misteriosos.",
  str_help_season1_disc_504 = "A Imprint das Memórias documenta os momentos notáveis vivenciados no sonho e pistas para adquirir conteúdo que ainda não foi coletado.",
  str_help_season1_disc_505 = "A Memória Sônica captura trechos de melodias ouvidas no sonho, junto com pistas para adquirir conteúdo não coletado.",
  str_help_season2_tab_1 = "Provas Entre Ondas Douradas",
