  str_help_season2_title_501 = "Exposição do Caso",
  str_help_season2_title_502 = "Tesouro sem nome",
  str_help_season2_title_503 = "Marca das memórias",
  str_help_season2_title_504 = "memória sônica",
  str_help_season2_disc_101 = "Silêncio, silêncio! Julgamentos Entre Ondulações Douradas estão em sessão agora!",
  str_help_season2_disc_102 = "Guie Irridon na utilização de seus pontos de Astúcia para conquistar a Margem dentro do sonho. Ao resolvê-lo, você terá acesso aos Contrapesos da Alma e à Vela da Justiça, que podem ser trocados por uma variedade de recompensas no Leilão de Julgamento, incluindo o traje Fiat Iustitia.",
  str_help_season2_disc_103 = "Complete as missões na Lista de Tarefas para receber Lumâmbar como recompensa.",
  str_help_season2_disc_104 = "Complete missões no mundo dos sonhos para adquirir o conjunto Stand By Me.",
  str_help_season2_disc_105 = "Todas as evidências coletadas dentro do sonho são metodicamente categorizadas e armazenadas por Irridon aqui.",
  str_help_season2_disc_201 = "Trials Amongst Golden Ripples já está em andamento, mas a Edge está dificultando o despertar de Irridon. Ajude Irridon a lidar com a Edge e você será recompensado generosamente pelo sucesso. Observe que cada desafio contra a Edge consumirá 1 ponto de Wit.",
  str_help_season2_disc_202 = "Existem dois níveis de dificuldade para o desafio Edge: Reverie e Pesadelo.\nEmbora Pesadelo ofereça uma experiência mais desafiadora, também proporciona recompensas superiores. Se você achar Pesadelo muito difícil, considere tentar Reverie primeiro.\nNo mesmo desafio Edge, o nível de estrelas alcançado em Pesadelo será sincronizado com Reverie. Conseguir uma recompensa de três estrelas e a 1ª Recompensa de Limpeza em Pesadelo também concederá a você recompensas correspondentes de Reverie.",
  str_help_season2_disc_203 = "Visite os Detalhes do Estágio para ver todas as informações de Edge relacionadas aos Trials Amongst Golden Ripples, onde você também pode alternar entre Reverie e Pesadelo.",
  str_help_season2_disc_204 = "A chave para manter um senso de racionalidade e clareza, permitindo que ela desafie a Borda nos Testes Entre Ondulações Douradas. Os pontos de perspicácia serão repostos em 3 pontos todos os dias às 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season2_disc_205 = "O Foco da Verdade pode fornecer uma forte assistência ao longo do caminho.\nTriunfe sobre a Borda sob a dificuldade de Pesadelos para obter a Luz da Justiça. O item pode aumentar o nível do Foco da Verdade.",
  str_help_season2_disc_206 = "Há pistas misteriosas e evidências físicas em Cognova e nos Arquivos de Casos, que serão organizadas no Expositor de Casos após a aquisição.",
  str_help_season2_disc_207 = "A Névoa Mística bloqueia o caminho de Irridon e turva seu coração. Derrote os Edges ao seu redor para dissipar a Névoa Mística!",
  str_help_season2_disc_208 = "Colete pistas e use a Balança da Justiça para dedução e resolver os casos encontrados!",
  str_help_season2_disc_209 = "Ah, não, um enxame de Devoradores de Sonhos está roendo o sonho de Irridon! Se o sonho dela desmoronar, a pobre Irridon pode nunca mais acordar... Não podemos deixar isso acontecer!\nUm novo enxame de Devoradores de Sonhos surge às 05:00 diariamente. Você terá 5 chances de expulsá-los todos os dias, sendo que as 2 primeiras expulsões bem-sucedidas oferecem recompensas generosas. A dificuldade de expulsar esses Devoradores de Sonhos aumenta a cada tentativa até ser reiniciada às 05:00 do dia seguinte.",
  str_help_season2_disc_301 = "O Leilão de Julgamento oferece uma seleção de recompensas, entre as quais está o traje Fiat Iustitia.",
  str_help_season2_disc_302 = "Resolva o Limite no sonho para adquirir Contrapesos da Alma e Vela da Justiça.",
  str_help_season2_disc_303 = "Contrapesos da Alma podem ser trocados pelo traje Fiat Iustitia, e a Vela da Justiça pode ser trocada por várias outras recompensas.",
  str_help_season2_disc_304 = "Após o encerramento do Leilão de Teste, os Contrapesos da Alma serão convertidos em Fragmentos de Sonho na proporção de 1:1, enquanto a Vela da Justiça será trocada por Nightium na proporção de 1:30. Os itens correspondentes serão enviados diretamente para você por correio.",
  str_help_season2_disc_305 = "Após o término do Leilão de Julgamento, o traje Fiat Iustitia ainda estará disponível nos Sonhos Autênticos. Nesse momento, você poderá trocar Fragmentos de Sonho, que são convertidos a partir de Contrapesos da Alma, pelo traje.",
  str_help_season2_disc_401 = "Complete as missões na Lista de Tarefas para receber Lumâmbar como recompensa.",
  str_help_season2_disc_402 = "Complete a Missão correspondente para obter Lumâmbar como recompensa.",
  str_help_season2_disc_501 = "Todas as evidências coletadas dentro do sonho são metodicamente categorizadas e armazenadas por Irridon aqui.",
  str_help_season2_disc_502 = "Tesouros Não Nomeados contêm itens colecionáveis encontrados no sonho, juntamente com pistas para adquirir conteúdo que ainda não foi coletado.",
  str_help_season2_disc_503 = "A Imprint das Memórias documenta os momentos notáveis vivenciados no sonho e pistas para adquirir conteúdo que ainda não foi coletado.",
  str_help_season2_disc_504 = "A Memória Sônica captura trechos de melodias ouvidas no sonho, junto com pistas para adquirir conteúdo não coletado.",
