  str_help_season3_title_504 = "memória sônica",
  str_help_season3_disc_101 = "Após viajar pelo buraco do coelho sob a água, será o lugar onde Connolly canta uma fantasia subaquática ou um vórtice do passado...",
  str_help_season3_disc_102 = "Guie Connolly para ajudá-la a conquistar o Vórtice dentro do sonho. Ao resolvê-lo, você terá acesso a Conchas Ecoantes e Fluorophora Deliciosas. Esses itens podem ser trocados por várias recompensas no Sea Bubbles Cafe, incluindo a roupa Aquatic Reverie.",
  str_help_season3_disc_103 = "Complete missões no Dreamy Prelude para obter Lumâmbar.",
  str_help_season3_disc_104 = "Complete missões no mundo dos sonhos para adquirir o conjunto Stand By Me.",
  str_help_season3_disc_105 = "Todos os itens coletados no sonho são categorizados e armazenados aqui de forma metódica por Connolly.",
  str_help_season3_disc_201 = "As portas para o País das Maravilhas foram abertas, mas o Vórtice está atrapalhando o avanço de Connolly. Ajude Connolly a derrotar o Vórtice e receba recompensas generosas pelo seu sucesso. Observe que cada desafio contra o Vórtice consumirá 1 ponto de Sabedoria.",
  str_help_season3_disc_202 = "Existem dois níveis de dificuldade para o desafio Vortex: Reverie e Pesadelo.\nEmbora o Pesadelo ofereça uma experiência mais desafiadora, ele também proporciona recompensas superiores. Se você achar o Pesadelo muito difícil, considere tentar o Reverie primeiro.\nNo mesmo desafio Vortex, o nível de estrela alcançado no Pesadelo será sincronizado com o Reverie. Conseguir uma recompensa de três estrelas e a 1ª Recompensa de Limpeza no Pesadelo também concederá a você as recompensas correspondentes do Reverie.",
  str_help_season3_disc_203 = "Visite os Detalhes do Estágio para ver todas as informações do Vortex relacionadas à Fantasia Subaquática, onde você também pode alternar entre Reverie e Pesadelo.",
  str_help_season3_disc_204 = "A chave para manter um senso de racionalidade e clareza, permitindo que ela desafie o Vórtice em Fantasia Subaquática. Os pontos de perspicácia serão repostos em 3 pontos todos os dias às 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season3_disc_205 = "Aqua Connection pode fornecer uma forte assistência ao longo do caminho.\nTriunfe sobre o Vortex sob a dificuldade Nightmares para obter o Estudo do Pact. O item pode melhorar o nível de Aqua Connection.",
  str_help_season3_disc_206 = "Há pistas misteriosas na Concha do Tesouro, que serão organizadas no Connolly Guarda-roupa após a aquisição.",
  str_help_season3_disc_207 = "A Inquietação bloqueou o caminho de Connolly. Derrote o Vórtice ao seu redor para dissipar a Inquietação!",
  str_help_season3_disc_301 = "O Sea Bubbles Cafe oferece uma seleção de recompensas, entre as quais está o traje Aquatic Reverie.",
  str_help_season3_disc_302 = "Resolva o Vórtice no sonho para adquirir Conchas Ecoantes e Fluorophora Deliciosas.",
  str_help_season3_disc_303 = "As Conchas Ecoantes podem ser trocadas pela roupa Aquatic Reverie, e o Delicioso Fluorophora pode ser trocado por várias outras recompensas.",
  str_help_season3_disc_304 = "Após o fechamento do Sea Bubbles Cafe, as Conchas Ecoantes serão convertidas em Fragmentos de Sonho na proporção de 1:1, enquanto o Delicioso Fluorophora será trocado por Nightium na proporção de 1:30. Os itens correspondentes serão enviados diretamente para você por correio.",
  str_help_season3_disc_305 = "Após o fechamento do Sea Bubbles Cafe, a roupa Aquatic Reverie ainda estará disponível em Authentic Dreamscapes. Nesse momento, você poderá trocar Dream Shards, que são convertidos de Echoing Seashells, pela roupa.",
  str_help_season3_disc_401 = "Complete missões no Dreamy Prelude para obter Lumâmbar e outras recompensas.",
  str_help_season3_disc_402 = "Complete as missões correspondentes para obter Lumamber e outras recompensas.",
  str_help_season3_disc_501 = "All the items gathered in the dream are methodically categorized and stored here by Connolly.",
  str_help_season3_disc_502 = "Tesouros Não Nomeados contêm itens colecionáveis encontrados no sonho, juntamente com pistas para adquirir conteúdo que ainda não foi coletado.",
